-- Generated by scripts/build-retention-demo.ts from src/lib/retention/demo-data.ts. Do not edit by hand.
-- Run with: npm run retention:generate
--
-- Fictional demo records for the Student Retention Agent, dated from today in Sydney, and
-- the reset the website calls with the main demo reset. Only rows labelled
-- 'fictional_demo' are ever removed.

create or replace function public.retention_demo_seed() returns void
language plpgsql as $$
declare
  d date := (now() at time zone 'Australia/Sydney')::date;
  v_owner uuid := (select id from public.app_users where role = 'owner' order by created_at limit 1);
begin
  -- The students and parents come from the Payments demo. Without them there is nothing to add.
  if not exists (select 1 from public.billing_students where id = 'ST-01' and data_label = 'fictional_demo') then
    return;
  end if;



  values ('ST-03', 'BC-02', 'email', 'Daniel O''Brien', 'daniel.obrien@example.com', 'Checking in about Liam''s Physics lessons', 'Hi Daniel,

I hope you''re well. I wanted to check in to see how Liam''s Physics lessons have been going and whether the lesson times are still working for your family.

We know the term can get busy, and we''re happy to help in whatever way suits you best, whether that''s a different lesson time, a short catch-up with Aisha or a change to the lesson plan.

Would you be open to a quick 10-minute call this week? Just reply with a time that works for you, or let us know if you''d prefer to chat by text.

Kind regards,
Alex Chen
Tutor Compass', 'sent', 2, v_owner, v_owner, ((d - 25)::timestamp + time '09:45') at time zone 'Australia/Sydney',
          public.retention_message_hash('email', 'daniel.obrien@example.com', 'Checking in about Liam''s Physics lessons', 'Hi Daniel,

I hope you''re well. I wanted to check in to see how Liam''s Physics lessons have been going and whether the lesson times are still working for your family.

We know the term can get busy, and we''re happy to help in whatever way suits you best, whether that''s a different lesson time, a short catch-up with Aisha or a change to the lesson plan.

Would you be open to a quick 10-minute call this week? Just reply with a time that works for you, or let us know if you''d prefer to chat by text.

Kind regards,
Alex Chen
Tutor Compass'), v_owner, ((d - 25)::timestamp + time '10:00') at time zone 'Australia/Sydney', 'simulated', 'Demo mode: simulated, nothing was sent',
          'received', ((d - 23)::timestamp + time '16:20') at time zone 'Australia/Sydney', 'Daniel replied that Saturday mornings suit Liam better. Lessons moved to Saturdays.', 'resolved', d - 18, 'demo', ((d - 25)::timestamp + time '09:45') at time zone 'Australia/Sydney', ((d - 23)::timestamp + time '16:20') at time zone 'Australia/Sydney');
  values ('ST-06', 'BC-05', 'sms', 'Sarah Chen', '+61 412 555 105', null, 'Hi Sarah, it''s Alex from Tutor Compass. Just checking in on how Oliver''s Mathematics lessons are going and whether the current lesson plan still suits you. We''re happy to help with times or anything else. Reply here or give us a call anytime.', 'sent', 2, v_owner, v_owner, ((d - 10)::timestamp + time '09:45') at time zone 'Australia/Sydney',
          public.retention_message_hash('sms', '+61 412 555 105', null, 'Hi Sarah, it''s Alex from Tutor Compass. Just checking in on how Oliver''s Mathematics lessons are going and whether the current lesson plan still suits you. We''re happy to help with times or anything else. Reply here or give us a call anytime.'), v_owner, ((d - 10)::timestamp + time '10:00') at time zone 'Australia/Sydney', 'simulated', 'Demo mode: simulated, nothing was sent',
          'none', null, null, 'scheduled', d - 3, 'demo', ((d - 10)::timestamp + time '09:45') at time zone 'Australia/Sydney', ((d - 10)::timestamp + time '10:00') at time zone 'Australia/Sydney');

  select 'simulated', format('Demo history: a check-in to %s was simulated. Nothing was sent.', m.recipient_name), m.student_id, 'demo', m.sent_at
  from public.retention_messages m where m.data_label = 'fictional_demo';

end $$;

-- Puts the retention demo back as it started.
create or replace function public.reset_retention_demo() returns jsonb
language plpgsql as $$
begin
  perform pg_advisory_xact_lock(hashtext('tutor_compass_retention_reset'));
  delete from public.retention_events where data_label = 'fictional_demo';
  delete from public.retention_messages where data_label = 'fictional_demo';
  delete from public.retention_alert_state where data_label = 'fictional_demo';
  delete from public.retention_dismissals where data_label = 'fictional_demo';
  delete from public.retention_runs where data_label = 'fictional_demo';
  delete from public.retention_concerns where data_label = 'fictional_demo';
  delete from public.retention_lessons where data_label = 'fictional_demo';
  perform public.retention_demo_seed();
  return jsonb_build_object('resetAt', now(), 'lessons', (select count(*) from public.retention_lessons where data_label = 'fictional_demo'));
end $$;

revoke all on function public.retention_demo_seed() from public, anon, authenticated;
revoke all on function public.reset_retention_demo() from public, anon, authenticated;

-- First load: add the demo records if there are none yet.
do $$
begin
  if not exists (select 1 from public.retention_lessons) then
    perform public.retention_demo_seed();
  end if;
end $$;
